  @protected
  void sse_encode_mint_request_status_ffi(
    MintRequestStatusFfi self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case MintRequestStatusFfi_Pending():
        sse_encode_i_32(0, serializer);
      case MintRequestStatusFfi_Denied(timestamp: final timestamp):
        sse_encode_i_32(1, serializer);
        sse_encode_u_64(timestamp, serializer);
      case MintRequestStatusFfi_Offered():
        sse_encode_i_32(2, serializer);
      case MintRequestStatusFfi_Accepted():
        sse_encode_i_32(3, serializer);
      case MintRequestStatusFfi_MintingEnabled():
        sse_encode_i_32(4, serializer);
      case MintRequestStatusFfi_Rejected(timestamp: final timestamp):
        sse_encode_i_32(5, serializer);
        sse_encode_u_64(timestamp, serializer);
      case MintRequestStatusFfi_Cancelled(timestamp: final timestamp):
        sse_encode_i_32(6, serializer);
        sse_encode_u_64(timestamp, serializer);
      case MintRequestStatusFfi_Expired(timestamp: final timestamp):
        sse_encode_i_32(7, serializer);
        sse_encode_u_64(timestamp, serializer);
    }
  }

